final class BoundedQueue[T](cap: Int) {
  private val q = scala.collection.mutable.ArrayDeque.empty[T]
  private val lock = new Object

  def put(item: T): Unit = lock.synchronized {
    while (q.size >= cap) lock.wait()      // JVM monitor condition
    q.append(item)
    lock.notifyAll()
  }
}

