private val lock = new ReentrantLock()
private val notFull = lock.newCondition()
private val notEmpty = lock.newCondition()

def put(item: T): Unit = {
  lock.lock()
  try {
    while (q.size >= cap) notFull.await()   // timed: awaitNanos
    q.append(item)
    notEmpty.signal()
  } finally lock.unlock()
}
